#
# Generate the Pi 4 GENET DTB fixtures from the documented node shapes. The values are
# transcribed facts from the Pi 4 firmware DTB and the bcm2711 DTS; see README.md for the
# citations. The fixtures are our own minimal trees, not copies of a donor DTB.
#
# Run from the repository root: python3 tests/fixtures/pi4-genet/generate.py

from __future__ import annotations

import struct
from pathlib import Path

FDT_MAGIC = 0xD00D_FEED
FDT_BEGIN_NODE = 1
FDT_END_NODE = 2
FDT_PROP = 3
FDT_END = 9

ROOT_CELLS = [0x2, 0x2]
MEMORY_REG = [0x0, 0x0, 0x0, 0x4000_0000]
SCB_RANGES = [
    0x0, 0x7C00_0000, 0x0, 0xFC00_0000, 0x0, 0x0380_0000,
    0x6, 0x0000_0000, 0x6, 0x0000_0000, 0x0, 0x4000_0000,
]
SCB_DMA_RANGES = [
    0x4, 0x7C00_0000, 0x0, 0xFC00_0000, 0x0, 0x0380_0000,
    0x0, 0x0000_0000, 0x0, 0x0000_0000, 0x4, 0x0000_0000,
]
GENET_REG = [0x0, 0x7D58_0000, 0x0, 0x1_0000]
GENET_INTERRUPTS = [0x0, 0x9D, 0x4, 0x0, 0x9E, 0x4]
MDIO_REG = [0xE14, 0x8]
PHY_REG = [0x1]
MAC = [0x02, 0x00, 0x00, 0x00, 0x00, 0x42]


class Node:
    def __init__(self, name: str, props=None, children=None):
        self.name = name
        self.props = props or []
        self.children = children or []


def text(name: str, value: str):
    return (name, "str", value)


def text_list(name: str, values):
    return (name, "strings", list(values))


def cells(name: str, values):
    return (name, "cells", list(values))


def bytes_prop(name: str, values):
    return (name, "bytes", list(values))


def flag(name: str):
    return (name, "empty", None)


def encode_prop(kind: str, value) -> bytes:
    if kind == "str":
        return value.encode() + b"\0"
    if kind == "strings":
        return b"".join(item.encode() + b"\0" for item in value)
    if kind == "cells":
        return b"".join(struct.pack(">I", item) for item in value)
    if kind == "bytes":
        return bytes(value)
    if kind == "empty":
        return b""
    raise ValueError(f"unknown property kind {kind}")


def dts_prop(kind: str, value) -> str:
    if kind == "str":
        return f'"{value}"'
    if kind == "strings":
        return ", ".join(f'"{item}"' for item in value)
    if kind == "cells":
        return "<" + " ".join(f"0x{item:x}" for item in value) + ">"
    if kind == "bytes":
        return "[" + " ".join(f"{item:02x}" for item in value) + "]"
    if kind == "empty":
        return ""
    raise ValueError(f"unknown property kind {kind}")


def build_blob(root: Node) -> bytes:
    strings = bytearray()
    offsets: dict[str, int] = {}

    def string_offset(name: str) -> int:
        if name not in offsets:
            offsets[name] = len(strings)
            strings.extend(name.encode() + b"\0")
        return offsets[name]

    def emit(node: Node) -> bytes:
        out = bytearray(struct.pack(">I", FDT_BEGIN_NODE))
        out.extend(node.name.encode() + b"\0")
        out.extend(b"\0" * ((4 - len(out) % 4) % 4))
        for name, kind, value in node.props:
            encoded = encode_prop(kind, value)
            out.extend(struct.pack(">III", FDT_PROP, len(encoded), string_offset(name)))
            out.extend(encoded)
            out.extend(b"\0" * ((4 - len(encoded) % 4) % 4))
        for child in node.children:
            out.extend(emit(child))
        out.extend(struct.pack(">I", FDT_END_NODE))
        return bytes(out)

    structure = emit(root) + struct.pack(">I", FDT_END)
    off_rsv = 40
    off_struct = off_rsv + 16
    off_strings = off_struct + len(structure)
    total = off_strings + len(strings)
    total = (total + 3) & ~3
    header = struct.pack(
        ">10I",
        FDT_MAGIC,
        total,
        off_struct,
        off_strings,
        off_rsv,
        17,
        16,
        0,
        len(strings),
        len(structure),
    )
    blob = bytearray(header)
    blob.extend(struct.pack(">QQ", 0, 0))
    blob.extend(structure)
    blob.extend(strings)
    blob.extend(b"\0" * (total - len(blob)))
    return bytes(blob)


def dts(root: Node, name: str) -> str:
    lines = [
        "// SPDX-License-Identifier: BSD-3-Clause",
        "// Copyright (c) 2026, Bo Maryniuk and RavenBSD contributors",
        f"// Generated by tests/fixtures/pi4-genet/generate.py; fixture {name}.",
        "/dts-v1/;",
        "",
    ]

    def emit(node: Node, indent: int) -> None:
        label = node.name or "/"
        lines.append(" " * indent + f"{label} {{")
        for prop_name, kind, value in node.props:
            rendered = dts_prop(kind, value)
            suffix = f" = {rendered}" if rendered else ""
            lines.append(" " * (indent + 4) + f"{prop_name}{suffix};")
        for child in node.children:
            emit(child, indent + 4)
        lines.append(" " * indent + "};")

    emit(root, 0)
    return "\n".join(lines) + "\n"


def genet_node(*, mac: bool, phy_mode: str, bad_mdio: bool) -> Node:
    props = [
        text("compatible", "brcm,bcm2711-genet-v5"),
        cells("reg", GENET_REG),
        cells("#address-cells", [0x1]),
        cells("#size-cells", [0x1]),
        cells("interrupts", GENET_INTERRUPTS),
        text("status", "okay"),
        text("phy-mode", phy_mode),
        cells("phy-handle", [0x1]),
    ]
    if mac:
        props.append(bytes_prop("local-mac-address", MAC))
    mdio_props = [
        text("compatible", "brcm,genet-mdio-v5"),
        cells("reg", [0xE14] if bad_mdio else MDIO_REG),
        text("reg-names", "mdio"),
        cells("#address-cells", [0x1]),
        cells("#size-cells", [0x0]),
    ]
    phy = Node(
        "ethernet-phy@1",
        [
            text("compatible", "ethernet-phy-ieee802.3-c22"),
            cells("reg", PHY_REG),
            cells("phandle", [0x1]),
        ],
    )
    return Node(
        "ethernet@7d580000",
        props,
        [Node("mdio@e14", mdio_props, [phy])],
    )


def platform(*, mac: bool = True, phy_mode: str = "rgmii-rxid", bad_mdio: bool = False) -> Node:
    scb = Node(
        "scb",
        [
            text("compatible", "simple-bus"),
            cells("#address-cells", [0x2]),
            cells("#size-cells", [0x2]),
            cells("ranges", SCB_RANGES),
            cells("dma-ranges", SCB_DMA_RANGES),
        ],
        [genet_node(mac=mac, phy_mode=phy_mode, bad_mdio=bad_mdio)],
    )
    return Node(
        "",
        [
            text_list("compatible", ["raspberrypi,4-model-b", "brcm,bcm2711"]),
            text("model", "Raspberry Pi 4 Model B"),
            cells("#address-cells", [ROOT_CELLS[0]]),
            cells("#size-cells", [ROOT_CELLS[1]]),
        ],
        [
            Node("aliases", [text("ethernet0", "/scb/ethernet@7d580000")]),
            Node(
                "memory@0",
                [text("device_type", "memory"), cells("reg", MEMORY_REG)],
            ),
            scb,
        ],
    )


def hex_dump(data: bytes) -> str:
    return "\n".join(data[index:index + 32].hex() for index in range(0, len(data), 32)) + "\n"


def main() -> None:
    here = Path(__file__).resolve().parent
    fixtures = {
        "pi4-genet-valid": platform(),
        "pi4-genet-no-mac": platform(mac=False, phy_mode="rgmii-id"),
        "pi4-genet-bad-mdio": platform(bad_mdio=True),
    }
    for name, root in fixtures.items():
        blob = build_blob(root)
        (here / f"{name}.dtb").write_bytes(blob)
        (here / f"{name}.dtb.hex").write_text(hex_dump(blob), encoding="ascii")
        (here / f"{name}.dts").write_text(dts(root, name), encoding="utf-8")


if __name__ == "__main__":
    main()
